namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokZustatekKnihyTab extends GContentBase {

        model: Gordic.Hpl.Interface.GPokStavKnihyDto;
        ciziMena: boolean;
        ixpDen: string;

        onContentReady() {

            var that = this;

            Gordic.Isl.PokKniha.stavAktualni(rq => { return { ixpDen: that.ixpDen} })
                .getData()
                .done(function (dto: Gordic.Hpl.Interface.GPokStavKnihyDto) {                 

                    that.model = dto;
                    that.ciziMena = that.model.mena != 0;



                    var tabmanager = $("<div>")
                        .appendTo(that.element)
                        .gtabmanager({
                            groups: [
                                {
                                    id: "groupAktualniStav",
                                    caption: "Aktuální zůstatek pokladny"
                                },
                                {
                                    id: "groupKDatu",
                                    caption: "Zůstatek pokladny k datu"
                                },
                                {
                                    id: "groupObdobi",
                                    caption: "Zůstatek pokladny za období"
                                },
                                {
                                    id: "groupEvidovane",
                                    caption: "jres:31302496"
                                }
                            ],
                            scopeElement: that.element
                        });


                  
                    let groupAktualniStav = $("<div>").appendTo(that.element)
                        .ggroupable({
                            group: { id: "groupAktualniStav" },
                            conceal: function (ev, ctx) {
                                if (ctx.conceal) groupAktualniStav.addClass("concealed"); else groupAktualniStav.removeClass("concealed");
                            }
                        });

                  
                    let groupKDatu = $("<div>").appendTo(that.element)
                        .ggroupable({
                            group: { id: "groupKDatu" },
                            conceal: function (ev, ctx) {                      
                                if (ctx.conceal) groupKDatu.addClass("concealed"); else groupKDatu.removeClass("concealed");
                            }
                        });

                  
                    let groupObdobi = $("<div>").appendTo(that.element)
                        .ggroupable({
                            group: { id: "groupObdobi" },
                            conceal: function (ev, ctx) {
                                if (ctx.conceal) groupObdobi.addClass("concealed"); else groupObdobi.removeClass("concealed");
                            }
                        });

                   
                    let groupEvidovane = $("<div>").appendTo(that.element)
                        .ggroupable({
                            group: { id: "groupEvidovane" },
                            conceal: function (ev, ctx) {
                                if (ctx.conceal) {
                                    groupEvidovane.addClass("concealed");
                                }


                                else {

                                    Gordic.Isl.PokKniha.stavEvidovanych(rq => { return { ixpDen: that.ixpDen } })
                                        .getData()
                                        .done(function (dto: Gordic.Hpl.Interface.GPokStavKnihyDto) {
                                            that.findFields().gfield("model", "apply", dto);
                                        });

                                    groupEvidovane.removeClass("concealed");
                                }
                            }
                        });

                    var tab1 = new Gordic.Forms.Form({ name: "form1" })        
                .addRow("jres:31302479") //RC 31302479 : Aktuální stav pokladny CZK
                .addField("gnumberbox", Gordic.Prefabs.Number.currency() ,{ name: "c_zustatek_akt", disabled: true })
                .addRow(("jres:31302480" + that.model.mena_zkr)) //RC 31302480 : Aktuální stav pokladny
                .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "c_zustatek_m_akt", disabled: true })
                .addRow("jres:31302481") //RC 31302481 : Chyba zaokrouhlení CZK
                .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "chyba_zaokrouhleni_akt", disabled: true });

                    $("<div>").appendTo(groupAktualniStav).gform("createFrom", tab1);
        

               var tab2 = new Gordic.Forms.Form({ name: "form2" })
             
                .addRow("jres:31302476")//RC 31302476 : Stav k datu
                .addField("gdatebox",
                    {
                        name: "k_datu",
                        change: function (ev, changeObj) {
                            if (changeObj.value) {

                                Gordic.Isl.PokKniha.stavKDatu(rq => { return { ixpDen: that.ixpDen, datum: changeObj.value! } })
                                    .getData()
                                    .done(function (dto: Gordic.Hpl.Interface.GPokStavKnihyDto) {
                                        that.findFields().gfield("model", "apply", dto);
                                    })

                            }
                        }
                    })
                .addRow("jres:31302483") //RC 31302483 : Stav k datu v CZK
                   .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "c_zustatek_dat", disabled: true})
                .addRow("jres:31302484 " + that.model.mena_zkr) //RC 31302484 : Stav k datu v 
                   .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "c_zustatek_m_dat", disabled: true})
                .addRow("jres:31302485") //RC 31302485 : Chyba zaokrouhlení k datu v CZK
                   .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "chyba_zaokrouhleni_dat", disabled: true });

         
                    $("<div>").appendTo(groupKDatu).gform("createFrom", tab2);
            

                    var tab3 = new Gordic.Forms.Form({ name: "form3", tabOptions: { title: "jres:31302486", opened: false } } as any)
                        .addRow("Od - do")
                        .addField("gintervalbox", {
                            name: "datum_od_do",
                            change: function (ev, changeObj) {
                                if (changeObj != null) {
                                    Gordic.Isl.PokKniha.pohybZaObdobi(rq => { return { ixpDen: that.ixpDen, datum: changeObj.value! } })
                                        .getData()
                                        .done(function (dto: Gordic.Hpl.Interface.GPokStavKnihyDto) {
                                            that.findFields().gfield("model", "apply", dto);
                                        })
                                }
                            }
                        })
                        .addSection("jres:31302488") //RC 31302488 : Hotovostní
                        .addRow("jres:31302489") //RC 31302489 : Příjem CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "prijem_h", disabled: true })
                        .addRow("jres:31302490") //RC 31302490 : Výdej CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "vydej_h", disabled: true })
                        .addRow("jres:31302491") //RC 31302491 : Celkem CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "zustatek_h", disabled: true })
                        .addRow("jres:31302492" + that.model.mena_zkr) //RC 31302492 : Příjem
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "prijem_h_m", disabled: true })
                        .addRow("jres:31302493" + that.model.mena_zkr) //RC 31302493 : Výdej
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "vydej_h_m", disabled: true })
                        .addRow("jres:31302274" + that.model.mena_zkr) //RC 31302274 : Zůstatek
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "zustatek_h_m", disabled: true })
                        .addSection("jres:31302494") //RC 31302494 : Bezhotovnostní
                        .addRow("jres:31302489") //RC 31302489 : Příjem CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "prijem_b", disabled: true })
                        .addRow("jres:31302490") //RC 31302490 : Výdej CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "vydej_b", disabled: true })
                        .addRow("jres:31302491") //RC 31302491 : Celkem CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "zustatek_b", disabled: true })
                        .addRow("jres:31302492" + that.model.mena_zkr) //RC 31302492 : Příjem
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "prijem_b_m", disabled: true })
                        .addRow("jres:31302493" + that.model.mena_zkr) //RC 31302493 : Výdej
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "vydej_b_m", disabled: true })
                        .addRow("jres:31302274" + that.model.mena_zkr) //RC 31302274 : Zůstatek
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "zustatek_b_m", disabled: true })
                        .addRow("jres:31302495") //RC 31302495 : Chyba zaokrouhlení v CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "chyba_zaokrouhleni_obd", disabled: true })



                    $("<div>").appendTo(groupObdobi).gform("createFrom", tab3);


                    var tab4 = new Gordic.Forms.Form({
                        name: "form4", tabOptions: { title: "jres:31302496" }
                    } as any) //RC 31302496 : V evid. hot. dokladech
                        .addRow("jres:31302489") //RC 31302489 : Příjem CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "prijem_evid", disabled: true })
                        .addRow("jres:31302497") //RC 31302497 : Výdej CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "vydej_evid", disabled: true })
                        .addRow("jres:31302491") //RC 31302491 : Celkem CZK
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "zustatek_evid", disabled: true })
                        .addRow("jres:31302492" + that.model.mena_zkr) //RC 31302492 : Příjem 
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "prijem_m_evid", disabled: true })
                        .addRow("jres:31302493" + that.model.mena_zkr)  //RC 31302493 : Výdej 
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "vydej_m_evid", disabled: true })
                        .addRow("jres:31302274" + that.model.mena_zkr)//RC 31302274 : Zůstatek 
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), { name: "zustatek_m_evid", disabled: true })


                    $("<div>").appendTo(groupEvidovane).gform("createFrom", tab4);

                    that.skryjDleMeny();

                    that.findFields().gfield("model", "apply", dto);

                    tabmanager.gtabmanager("refresh");

                })

         

        }

        private skryjDleMeny(): void {

            var that = this;
      
            that.element.findForms("form1").findFormRows("field:c_zustatek_akt,field:chyba_zaokrouhleni_akt").toggle(that.ciziMena);
            that.element.findForms("form2").findFormRows("field:c_zustatek_dat,field:chyba_zaokrouhleni_dat").toggle(that.ciziMena);
            that.element.findForms("form3").findFormRows("field:prijem_h,field:vydej_h,field:zustatek_h,field:prijem_b,field:vydej_b,field:zustatek_b,field:chyba_zaokrouhleni_obd").toggle(that.ciziMena);
            that.element.findForms("form4").findFormRows("field:prijem_evid,field:vydej_evid,field:zustatek_evid").toggle(that.ciziMena);
        }
    }
}
